KG42.register("clusters-63d5029e496b7adbb91ecf54",{"id":"33-retail_market_interoperability::v142-d-CL004","paper":"33-retail_market_interoperability","label":"Permission for prosumers to participate with no upper bound on their number","record":{"cluster_id":"v142-d-CL004","label":"Permission for prosumers to participate with no upper bound on their number","market_meaning":"The proposed H-MG interoperability retail market allows any number of prosumers to participate. This candidate expresses only permission on number and does not add admission or identity-mapping rules that were not given.","mechanism_ids":["v141-a-M01"],"market_types":["LEM"],"process_stages":["participation"],"scope_disposition":"compatible","scope_explanation":"The scope of application is permission on the number of prosumers in this mechanism. It is not equivalent to the classification of consumer entities, and it cannot be used to replace the independent retailer role that is pending review.","assembly_status":"assembled","boundary_rationale":"Permission for prosumers to participate with no upper bound on their number can be understood independently. The existing sources do not give a necessary information dependence on the other participation chains, so the single-chain cluster is retained.","chain_bindings":[{"chain_id":"v141-c-R008","ownership":"primary","role":"core","rationale":"The frozen chain has fully expressed this narrow permission on number. It is not merged with consumer classification or retailer identity merely because they belong to the same participation stage."}],"connections":[],"object_mappings":[],"gaps":[{"gap_id":"v142-d-G015","category":"unverified_source","description":"The permission on number rests on an unaudited statement in the abstract. It cannot yet be concluded on this basis that the specific admission conditions, the method of aggregating players, or all extended instances have been verified against the source.","chain_ids":["v141-c-R008"],"object_refs":["v141-c-R008::phi::v141-c-R008-C001"],"evidence_ids":["v141-b-g01-E01"],"proposal_ids":[],"required_work":"Manually check the statement in the abstract and its scope of application in the main text. If prosumers are to be further linked to generator, consumer, or H-MG identities, explicit source support must be obtained separately."}]},"rule_refs":["33-retail_market_interoperability::v141-c-R008"],"unresolved_rule_refs":[],"node_ids":["COMP-2322f661e72aa8a6"]});
